import{_ as l,c as t,o as a,ae as o}from"./chunks/framework.Bi6zybwU.js";const m=JSON.parse('{"title":"Colspan/Cell Merge","description":"Colspan/Cell Merge","frontmatter":{"title":"Colspan/Cell Merge","description":"Colspan/Cell Merge"},"headers":[],"relativePath":"guide/table-formatting/colspan-cell-merge.md","filePath":"guide/table-formatting/colspan-cell-merge.md"}'),n={name:"guide/table-formatting/colspan-cell-merge.md"};function s(r,e,i,c,p,g){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="colspan-cell-merge" tabindex="-1">Colspan/Cell Merge <a class="header-anchor" href="#colspan-cell-merge" aria-label="Permalink to &quot;Colspan/Cell Merge&quot;">​</a></h1><p>This function joins multiple neighboring cells into a single larger cell. To merge multiple cells in a row, you must give your cells a value** <strong>as</strong> &quot;#colspan#,&quot;** and then see the selected cell merge with the subsequent cells. *******Please note that this function will operate with <strong>Advanced Table (Legacy) only.</strong></p><h2 id="how-to-merge-table-cells" tabindex="-1">How to Merge Table Cells <a class="header-anchor" href="#how-to-merge-table-cells" aria-label="Permalink to &quot;How to Merge Table Cells&quot;">​</a></h2><ul><li>To apply this Cell Merge feature, you have to create a table. Or you can edit any of the existing tables.</li><li>First, select a table and find the cells you want to merge.</li><li>Remember that when you merge columns, the cell merge option always takes the** **corresponding cell value into one single row. <img src="https://ninjatables.com/wp-content/uploads/2022/09/add-colspan-01.webp" alt=""></li><li>As you can see in the image above, we here want to merge some cells right below the header to create a separate header and another one in the middle of the table. Also, 2 cells at the end of the table will be merged into one using the same #colspan#. You will see the trick after you complete this step. The columns will merge automatically only in that particular row. Here&#39;s how the table looks. <img src="https://ninjatables.com/wp-content/uploads/2023/07/rowspan-1024x457.png" alt="colspan in table"> Also, You can apply the** #colspan# **instead of the column title (Job Position), and the column header will be merged with its previous one. <img src="https://ninjatables.com/wp-content/uploads/2022/09/Collapain-in-title-02.webp" alt=""> Here&#39;s an example of how merged table cells using &quot;colspan&quot; on the header looks like. <img src="https://ninjatables.com/wp-content/uploads/2023/07/rowspan-1024x457.png" alt="colspan in table"> Go to **Table Configuration → Rendering Settings **and set your table to <strong>Advanced Table (Legacy)</strong>. This will enable you to apply the Cell Merge feature in your Ninja Table. See <a href="https://ninjatables.com/docs/table-rendering-settings/" target="_blank" rel="noreferrer">Rendering Settings</a>.</li></ul>',4)])])}const u=l(n,[["render",s]]);export{m as __pageData,u as default};
